%dw 2.0
output application/json
fun applyOp(op: String, amount: Number) = (x: Number) -> op match {
  case "add" -> x + amount
  case "mul" -> x * amount
  else -> x
}
fun pipeline(base, rules) = rules reduce ((r, acc = base) -> then(acc, applyOp(r.op, r.amount)))
---
{
  addThenMul: pipeline(100, [{op: "add", amount: 10}, {op: "mul", amount: 2}]),
  mulThenAdd: pipeline(100, [{op: "mul", amount: 2}, {op: "add", amount: 10}])
}
